import secrets

class AccountService:
    def __init__(self) -> None:
        # email (normalized to lowercase) -> password (as provided, but compared case-insensitively)
        self._accounts: dict[str, str] = {}
        self._admins: set[str] = set()
        # token -> target email (normalized)
        self._reset_tokens: dict[str, str] = {}

    @staticmethod
    def _normalize_email(email: str) -> str:
        return email.lower()

    @staticmethod
    def _validate_password(password: str) -> None:
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        self._validate_password(password)
        norm = self._normalize_email(email)
        if norm in self._accounts:
            raise ValueError("An account with this email already exists.")
        self._accounts[norm] = password
        if is_admin:
            self._admins.add(norm)

    def login(self, email: str, password: str) -> bool:
        norm = self._normalize_email(email)
        stored = self._accounts.get(norm)
        if stored is None:
            return False
        return stored.lower() == password.lower()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester = self._normalize_email(requester_email)
        target = self._normalize_email(target_email)

        # Only existing accounts can request or be the target of a reset.
        if requester not in self._accounts:
            raise ValueError("Requester has no account.")
        if target not in self._accounts:
            raise ValueError("Target has no account.")

        # Only admins may request a reset for another user; users may reset their own.
        if requester != target and requester not in self._admins:
            raise ValueError("Not authorized to request reset for another user.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        self._validate_password(new_password)
        target = self._reset_tokens.pop(token, None)
        if target is None:
            raise ValueError("Invalid or already-used reset token.")
        self._accounts[target] = new_password
